<html>
<head>
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f4f6f9; color: #333; margin: 0; padding: 20px; }
    .container { max-width: 600px; background: #ffffff; border-radius: 12px; box-shadow: 0 4px 15px rgba(0,0,0,0.05); overflow: hidden; margin: 0 auto; border: 1px solid #eef2f5; }
    .header { background: linear-gradient(135deg, #e74c3c 0%, #c0392b 100%); color: #ffffff; padding: 30px 20px; text-align: center; }
    .header h1 { margin: 0; font-size: 22px; font-weight: 600; letter-spacing: 0.5px; }
    .header p { margin: 5px 0 0 0; opacity: 0.8; font-size: 14px; }
    .metrics { display: flex; padding: 20px; background: #fafbfc; border-bottom: 1px solid #eef2f5; justify-content: space-around; }
    .metric-card { text-align: center; flex: 1; padding: 10px; }
    .metric-val { font-size: 24px; font-weight: 700; color: #1e3c72; }
    .metric-lbl { font-size: 11px; text-transform: uppercase; color: #7f8c8d; margin-top: 5px; font-weight: 600; }
    .metric-val.passed { color: #2ecc71; }
    .metric-val.failed { color: #e74c3c; }
    .content { padding: 25px 20px; }
    .status-badge { display: inline-block; padding: 4px 10px; border-radius: 20px; font-size: 12px; font-weight: 600; text-transform: uppercase; }
    .status-badge.passed { background-color: #d4edda; color: #155724; }
    .status-badge.failed { background-color: #f8d7da; color: #721c24; }
    .table-container { margin-top: 20px; }
    table { width: 100%; border-collapse: collapse; text-align: left; }
    th { padding: 12px; border-bottom: 2px solid #eef2f5; color: #7f8c8d; font-size: 12px; text-transform: uppercase; font-weight: 600; }
    td { padding: 15px 12px; border-bottom: 1px solid #f4f6f9; font-size: 14px; }
    .test-title { font-weight: 600; color: #2c3e50; }
    .test-file { font-size: 11px; color: #95a5a6; margin-top: 2px; }
    .error-box { background: #fdf2f2; border-left: 3px solid #e74c3c; padding: 10px; font-family: monospace; font-size: 12px; color: #c0392b; overflow-x: auto; margin-top: 8px; border-radius: 4px; }
    .footer { background: #fafbfc; padding: 20px; text-align: center; font-size: 12px; color: #95a5a6; border-top: 1px solid #eef2f5; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>E2E Test Execution Failed</h1>
      <p>Project: {{$node["Webhook"].json["body"]["projectName"]}}</p>
    </div>
    <div class="metrics">
      <div class="metric-card">
        <div class="metric-val">{{$node["Webhook"].json["body"]["totalTests"]}}</div>
        <div class="metric-lbl">Total Runs</div>
      </div>
      <div class="metric-card">
        <div class="metric-val passed">{{$node["Webhook"].json["body"]["passed"]}}</div>
        <div class="metric-lbl">Passed</div>
      </div>
      <div class="metric-card">
        <div class="metric-val failed">{{$node["Webhook"].json["body"]["failed"]}}</div>
        <div class="metric-lbl">Failed</div>
      </div>
      <div class="metric-card">
        <div class="metric-val">{{($node["Webhook"].json["body"]["durationMs"] / 1000).toFixed(1)}}s</div>
        <div class="metric-lbl">Duration</div>
      </div>
    </div>
    <div class="content">
      <div class="table-container">
        <table>
          <thead>
            <tr>
              <th>Test Scenario</th>
              <th style="text-align: right;">Status</th>
            </tr>
          </thead>
          <tbody>
            {{$node["Webhook"].json["body"]["tests"].map(t => '<tr><td><div class="test-title">' + t.title + '</div><div class="test-file">' + t.file + ' &bull; ' + (t.durationMs/1000).toFixed(1) + 's</div>' + (t.errorMessage ? '<div class="error-box">' + t.errorMessage + '</div>' : '') + '</td><td style="text-align: right; vertical-align: top;"><span class="status-badge ' + (t.status === \'failed\' || t.status === \'timedout\' ? \'failed\' : \'passed\') + '">' + t.status + '</span></td></tr>').join('')}}
          </tbody>
        </table>
      </div>
    </div>
    <div class="footer">
      This is an automated notification from your n8n workflow.<br>Time of execution: {{$node["Webhook"].json["body"]["timestamp"]}} 
    </div>
  </div>
</body>
</html>

